// Extract base64 image from Imagen response and prepare upload payload
const imagenResponse = $json;
const videoId = $node['Webhook Trigger'].json.body.video_id;

let imageBase64 = '';
let imageKey = '';

try {
  if (imagenResponse.predictions && imagenResponse.predictions[0] && imagenResponse.predictions[0].bytesBase64Encoded) {
    imageBase64 = imagenResponse.predictions[0].bytesBase64Encoded;
    imageKey = 'hero/' + videoId + '-' + Date.now() + '.png';
  }
} catch (e) {
  // Imagen failed (continueOnFail) — no image to upload
}

return [{ json: { imageBase64, imageKey, hasImage: imageBase64.length > 0 } }];

// Assemble all data for publishing
const titleData = JSON.parse($node['Step 2: Title & Hooks (GPT-4o)'].json.choices[0].message.content);
const blogData = JSON.parse($node['Step 4: Blog Body (Sonnet 4.6)'].json.content[0].text);
const videoId = $node['Webhook Trigger'].json.body.video_id;

// Get hero image URL from upload result (if available)
let heroImageUrl = '';
try {
  const uploadResult = $node['Upload Hero Image to R2'].json;
  if (uploadResult && uploadResult.url) {
    heroImageUrl = uploadResult.url;
  }
} catch (e) {
  // Upload node didn't run or failed — no hero image
}

return [{
  json: {
    videoId,
    title: titleData.title,
    hook: titleData.hook,
    seoDesc: titleData.seo_description,
    heroImage: heroImageUrl,
    intro: blogData.intro,
    sections: blogData.sections,
    conclusion: blogData.conclusion,
    tags: blogData.tags,
    keywords: titleData.keywords,
    faq: blogData.faq || []
  }
}];
